package thaumcraft.research;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class ResearchProgressionTest {
 @Test void legitimatePastScansRecoverNewDiscoveriesWithoutNewRewards(){var old=KnowledgeState.EMPTY.scan("entity:minecraft:iron_golem").scan("entity:thaumcraft:cultist_knight").scan("entity:thaumcraft:firebat").addPoints("OBSERVATION","BASICS",17);var fixed=ResearchDiscovery.reconcile(old,false);assertTrue(fixed.flags().containsAll(Set.of("f_golem","!CrimsonCultist","!Firebat","f_BAT","f_FLY")));assertEquals(old.scans(),fixed.scans());assertEquals(old.points(),fixed.points());assertEquals(fixed,ResearchDiscovery.reconcile(fixed,false));assertTrue(ResearchCatalog.knows(fixed,"!CrimsonCultist"));assertTrue(ResearchCatalog.knows(fixed,"!CrimsonCultist@2"));assertFalse(ResearchCatalog.knows(fixed,"!CrimsonCultist@3"));}
 @Test void lastingWarpDiscoveryRequiresFinishedFirstSteps(){assertFalse(ResearchDiscovery.reconcile(KnowledgeState.EMPTY,true).flags().contains("WARP"));var done=KnowledgeState.EMPTY.stage("FIRSTSTEPS",ResearchCatalog.BY_KEY.get("FIRSTSTEPS").stages().size()+1);assertFalse(ResearchDiscovery.reconcile(done,false).flags().contains("WARP"));assertTrue(ResearchDiscovery.reconcile(done,true).flags().contains("WARP"));}
 @Test void oldRitesStudyIsRecognizedWithoutCompletingOtherPartialResearch(){var old=KnowledgeState.EMPTY.flag("CrimsonRites").flag("FIRSTSTEPS");assertTrue(ResearchCatalog.knows(old,"CrimsonRites"));assertFalse(ResearchCatalog.knows(old,"FIRSTSTEPS"));assertTrue(ResearchCatalog.knows(old,"CrimsonRites@3"));assertFalse(ResearchCatalog.knows(old,"CrimsonRites@4"));assertFalse(ResearchCatalog.knows(old,"CrimsonRites@bad"));assertEquals(0,old.stages().size());}
 @Test void advancedSealAddendaAndActualFirebatAreRetained(){assertEquals(16,ResearchCatalog.ENTRIES.stream().mapToInt(e->e.addenda().size()).sum());var collect=ResearchCatalog.BY_KEY.get("SEALCOLLECT");assertFalse(collect.stages().getFirst().recipes().contains("thaumcraft:SealCollectAdv"));assertEquals(List.of("MINDBIOTHAUMIC"),collect.addenda().getFirst().research());assertEquals(List.of("thaumcraft:SealCollectAdv"),collect.addenda().getFirst().recipes());assertTrue(ResearchCatalog.BY_KEY.get("FOCUSSPELLBAT").parents().contains("!Firebat"));assertFalse(ResearchCatalog.BY_KEY.get("FOCUSSPELLBAT").parents().contains("!minecraft:blaze"));}
}
